/** STEP pure notes: each STEP 3-only technique carries an explicit scope. */
import { tex as r, technique as t, linkedProblem as q } from './admissions-authoring.js';

export const stepPureContent = {
  'pure/algebra-proof': {
    bullets: [
      t('Induction with a stated range', '注明起点的数学归纳法', '归纳法先证明起点，再证明任意一个合法索引成立时下一个也成立，连接全部后续整数。', '归纳假设只用于推出下一步，起点和适用范围不能省略。', r`P(n_0),\quad P(k)\Rightarrow P(k+1)\quad(k\ge n_0)`, '明确命题和变量范围；证明基础情形，再使用任意 k 的假设完成下一项。', r`若 \(\sum_{j=1}^k(2j-1)=k^2\)，增加下一项 \(2k+1\) 后得到 \((k+1)^2\)。`, '仅验证许多整数不是归纳；证明下一步时不能直接假定下一步结论成立。'),
      t('Deduction, contradiction and equivalence', '演绎、反证与等价', '长题需要把每一步连接成完整论证；要求充要条件时，两个方向都要覆盖。', '推出必要条件后，仍需验证它是否充分。', r`P\iff Q\quad\Longleftrightarrow\quad(P\Rightarrow Q)\text{ and }(Q\Rightarrow P)`, '先拆目标，标明可逆与不可逆步骤；反证时准确否定目标并追踪矛盾来源。', '例如平方后得到候选根，只完成必要条件；逐一代入原方程才补足充分性。', '逆命题不因原命题正确就自动正确；引用前面小问时保留其条件。'),
      t('Polynomial root transformations', '多项式根的变换', '不逐个求根，直接对新变量做逆代换，就能构造变换后各根满足的多项式。', '新根为旧根的线性变换时，在原多项式中代入逆变换。', r`\beta=a\alpha+b,\ a\ne0\quad\Longrightarrow\quad P\!\left(\frac{y-b}{a}\right)=0`, '先用韦达关系整理对称式；构造新多项式后清分母，并确认次数与首项系数。', r`原根满足 \(x^2-3x+1=0\)，新根为旧根加一，则新方程为 \(y^2-5y+5=0\)。`, '根的变换和图像平移相关但不是同一句代换；倍数为零时不能使用逆代换。'),
      t('Division before partial fractions', '先除后拆的部分分式', '有理式分子次数不低于分母时，先做多项式除法，再按分母因式结构拆分。', '不可约二次因式一般配一次分子，重复因式必须保留各阶项。', r`\frac{R(x)}{(x-a)^2(x^2+c)}=\frac A{x-a}+\frac B{(x-a)^2}+\frac{Cx+D}{x^2+c}\quad(c>0,\ \deg R<4)`, '先因式分解并标记禁值，列完整分式形式，再用代入或系数比较求常数。', r`例如 \(\frac1{x(x+1)}=\frac1x-\frac1{x+1}\)，是后续积分和望远镜求和的共同入口。`, '不可约二次因式的分子不能只设常数；拆开的式子仍受原定义域约束。'),
      t('Inequalities with sign restrictions', '带符号限制的不等式', '把平方、乘除和单调函数用于不等式时，要显式保留正负与定义域条件。', '先确认操作保持方向，或按符号分情况讨论。', r`x>0\quad\Longrightarrow\quad x+\frac1x-2=\frac{(x-1)^2}{x}\ge0`, '优先把差写成非负量；对有理式使用零点与极点分段，不直接乘未知符号的分母。', r`例如上式同时说明 \(x+\frac1x\ge2\)，且等号只在 \(x=1\) 成立。`, '负分母会改变方向；证明最值还需指出等号确能在允许范围取得。'),
    ],
    exercises: [
      q('induction-growth', 'An induction with strictness', r`(i) Prove by induction that \(2^n\ge n+1\) for every integer \(n\ge0\). (ii) Determine exactly when equality holds.`, '归纳时比较两倍的已知下界与下一步目标；另查什么时候出现严格不等式。', [r`At \(n=0\), both sides equal 1. Assume \(2^k\ge k+1\) for an arbitrary \(k\ge0\). Then \(2^{k+1}\ge2k+2\ge k+2\), completing the induction.`, r`Equality holds for \(n=0,1\). In the step from \(k=1\) to \(k+1=2\), the second inequality is strict, and all subsequent steps remain strict. Thus equality holds exactly at 0 and 1.`], true),
      q('shifted-cubic', 'A shifted cubic and a symmetric sum', r`The roots of \(x^3-3x+1=0\), counted with multiplicity, are \(\alpha,\beta,\gamma\). (i) Find a monic polynomial whose roots are \(\alpha+1,\beta+1,\gamma+1\). (ii) Find the sum of the squares of these new roots without solving the cubic.`, '在原多项式代入新变量减一，再比较系数。', [r`Put \(x=y-1\). Then \((y-1)^3-3(y-1)+1=y^3-3y^2+3\), which is the required monic polynomial.`, r`The new roots have sum 3 and pairwise-product sum 0. Their squared sum is therefore \(3^2-2\cdot0=9\).`]),
    ],
  },
  'pure/functions': {
    bullets: [
      t('Restricted inverse functions', '限制定义域后求反函数', '一条水平线多次穿过图像时，函数在整个定义域上没有单值反函数，需要先选一条单调分支。', '先说明一一对应的定义域，再交换输入输出。', r`f^{-1}(f(x))=x\quad\text{on the chosen one-to-one domain}`, '求反函数前找值域；解出候选分支后，用原定义域选择正确符号。', r`例如 \(x^2\) 限制在非负实数上，反函数为主平方根；若限制在非正实数上则选负分支。`, '反函数符号不是倒数；一个代数表达式的所有分支不能同时作为同一个函数。'),
      t('Asymptotes and conic sections', '渐近线与圆锥曲线', '研究远处和分母为零附近的行为，再把对称与截距用于椭圆、双曲线和有理曲线的草图。', '渐近线描述极限行为，不保证曲线永远不能穿过它。', r`\frac{x^2}{a^2}-\frac{y^2}{b^2}=1\quad\Longrightarrow\quad y=\pm\frac ba x\ \text{asymptotically}`, '先标定义域、对称轴和截距，再求远处主导项；竖直渐近线需检查实际极限。', r`例如 \(y=\frac{x^2+1}{x}=x+\frac1x\) 以直线 \(y=x\) 为斜渐近线。`, '可约分因式可能只留下空点而非竖直渐近线；椭圆的横纵分母不是直接的轴长。'),
      t('Exponential and logarithmic modelling', '指数对数模型与线性化', '把幂律和指数律取对数，可转化为直线关系，斜率与截距分别编码模型参数。', '取对数前确保所有真数与底数条件合法。', r`y=Ax^p\Rightarrow\ln y=\ln A+p\ln x\quad(A,x,y>0)`, '明确采用哪组横纵变量；读出斜率后按对应模型解释，并检查数据是否支持恒定关系。', r`例如 \(y=3e^{2x}\) 给出 \(\ln y=\ln3+2x\)，对数纵轴与 x 的图为直线。`, '幂律的双对数图和指数律的半对数图不同；超出数据范围预测需要保留模型假设。'),
      t('Root location and Newton iteration', '根的定位与牛顿迭代', '连续函数异号可保证区间内存在根；牛顿法用当前切线的零点产生下一次近似。', '异号判根需要连续性，牛顿步需要导数非零。', r`x_{n+1}=x_n-\frac{f(x_n)}{f'(x_n)}`, '先给出根所在区间，再选初值并检查后续项是否保持合法、单调或有界。', r`求 \(\sqrt2\) 可对 \(f(x)=x^2-2\) 使用 \(x_{n+1}=\frac12(x_n+\frac2{x_n})\)。`, '越过竖直渐近线的变号不保证有根；牛顿法可能发散、循环或落到导数零点。'),
    ],
    exercises: [
      q('inverse-reciprocal', 'Choosing an inverse branch', r`Let \(f(x)=x+\frac1x\) for \(x>0\). (i) Show that \(f(x)\ge2\). (ii) Explain why it has no inverse on this entire domain. (iii) Restrict to \(x\ge1\) and find its inverse and the inverse domain.`, '先写成平方差，再注意互为倒数的两点具有相同函数值。', [r`We have \(f(x)-2=\frac{(x-1)^2}{x}\ge0\), with equality only at 1.`, r`For \(x\ne1\), the distinct inputs \(x\) and \(\frac1x\) have the same output, so the full function is not one-to-one.`, r`For \(x\ge1\), it is strictly increasing away from its endpoint and has range \([2,\infty)\). Solving \(y=x+\frac1x\) gives \(x=\frac{y\pm\sqrt{y^2-4}}2\). The branch \(x\ge1\) requires the plus sign, so \(f^{-1}(y)=\frac{y+\sqrt{y^2-4}}2\), for \(y\ge2\).`]),
      q('newton-square-root', 'Proving an iteration converges', r`Let \(u_1=2\) and \(u_{n+1}=\frac12\left(u_n+\frac2{u_n}\right)\). (i) Calculate \(u_2\). (ii) Show \(u_n\ge\sqrt2\) and \(u_{n+1}\le u_n\). (iii) Find the limit.`, '下一项减根号二可写成一个平方除以正数；再比较前后两项。', [r`The second term is \(u_2=\frac32\). For every positive \(u_n\), \(u_{n+1}-\sqrt2=\frac{(u_n-\sqrt2)^2}{2u_n}\ge0\). Thus all terms are at least \(\sqrt2\).`, r`Consequently, \(u_{n+1}-u_n=\frac{2-u_n^2}{2u_n}\le0\). The sequence is decreasing and bounded below, so it converges.`, r`If its limit is \(L\ge\sqrt2\), continuity gives \(L=\frac12(L+\frac2L)\). Hence \(L^2=2\), and \(L=\sqrt2\).`], true),
    ],
  },
  'pure/sequences': {
    bullets: [
      t('Method of differences for sums', '差分与望远镜求和', '把通项写成前后两项的差，求和后中间项消去，只剩容易漏掉的首尾。', '先展开前两项和末两项，确认消去边界。', r`\sum_{k=1}^n(v_k-v_{k+1})=v_1-v_{n+1}`, '尝试部分分式、幂差或移位；索引跨度超过一时可能留下多项边界。', r`例如 \(\frac1{k(k+1)}=\frac1k-\frac1{k+1}\)，从一求和到 n 只剩 \(1-\frac1{n+1}\)。`, '消去必须发生在同一有限和内；不能先将两个发散无穷和分别赋值后相减。'),
      t('Recurrence bounds and monotone limits', '递推的界与单调极限', '先证明区间在递推下保持，再证明单调，才有依据将极限代入递推规则。', '不动点是候选极限，单调有界提供收敛理由。', r`u_{n+1}=f(u_n),\quad u_n\to L\Rightarrow L=f(L)\quad\text{when }f\text{ is continuous at }L`, '用归纳建立上界或下界，再研究相邻项差的符号；按初值排除不合范围的不动点。', r`例如 \(u_{n+1}=\sqrt{2+u_n}\)、\(u_1=1\)，可先证明全部项落在一与二之间。`, '递推中含根号、分母或对数时，第一步还要证明每一项都有定义。'),
      t('Rational binomial expansions', '有理数幂二项式展开', '非整数幂通常展开成无穷级数，只能在指定收敛范围内使用，近似时还需明确截断阶数。', '先提取常数，把括号改成一加小量，并写绝对值小于一的条件。', r`(1+x)^a=1+ax+\frac{a(a-1)}{2!}x^2+\cdots\quad(|x|<1)`, '把整体变量对应到展开式中的小量，按目标阶数保留项并整理误差。', r`例如 \(\sqrt{1+x}=1+\frac x2-\frac{x^2}8+\cdots\)，在 \(|x|<1\) 内使用。`, '负整数或分数幂不是有限多项式；不能将仅局部有效的近似当作全局恒等式。'),
      t('The exponential series in STEP 2', 'STEP 2 的指数级数', '指数函数的阶乘分母展开已在 STEP 2 范围，可连接求和与泊松概率，不必等到 STEP 3。', '指数级数对所有实数自变量收敛。', r`e^x=\sum_{k=0}^{\infty}\frac{x^k}{k!}`, '识别阶乘分母与幂次；若从非零索引求和，先补齐缺失首项再扣除。', r`例如 \(\sum_{k=2}^{\infty}\frac1{k!}=e-2\)，去掉的是索引零和一的两项。`, '识别指数展开属 STEP 2，而一般函数的麦克劳林展开列在 STEP 3；两者范围不要混淆。'),
    ],
    exercises: [
      q('telescoping-tail', 'A finite sum and its tail', r`(i) Find \(S_n=\sum_{k=1}^n\frac1{k(k+1)}\). (ii) Find its limit. (iii) Determine the least positive integer \(n\) for which \(1-S_n<\frac1{100}\).`, '拆成相邻倒数之差；最后一步注意严格小于。', [r`Since \(\frac1{k(k+1)}=\frac1k-\frac1{k+1}\), the sum is \(S_n=1-\frac1{n+1}=\frac n{n+1}\).`, r`Its limit is 1. The tail is \(\frac1{n+1}\), which is strictly smaller than \(\frac1{100}\) exactly when \(n+1>100\). The least allowed integer is \(n=100\).`]),
      q('radical-recurrence', 'A bounded radical recurrence', r`Let \(u_1=1\) and \(u_{n+1}=\sqrt{2+u_n}\). (i) Prove \(1\le u_n<2\). (ii) Prove that the sequence is strictly increasing. (iii) Find its limit.`, '先证明区间不被递推带出；比较平方可避免复杂根式相减。', [r`The bound holds at 1. If \(1\le u_n<2\), then \(1<\sqrt{2+u_n}<2\), completing the induction.`, r`For \(1\le u_n<2\), \(2+u_n-u_n^2=(2-u_n)(u_n+1)>0\). Both sides being positive, this gives \(u_{n+1}>u_n\).`, r`Monotonicity and the upper bound imply convergence. The limit satisfies \(L=\sqrt{2+L}\), giving \(L=2\) or \(-1\). Only \(L=2\) is compatible with the bounds.`], true),
    ],
  },
  'pure/trigonometry': {
    bullets: [
      t('Compound angles and identity proofs', '和差角与恒等变形', '把不同角的三角函数改写到同一组角，可以发现因式、消去项和共同结构。', '证明恒等式时，从已知一侧合法变形，不通过除零偷换定义域。', r`\sin(A\pm B)=\sin A\cos B\pm\cos A\sin B`, '先观察和差角、二倍角或平方关系；若除以三角因子，先单列其为零的情况。', r`例如 \(\sin3x-\sin x=2\cos2x\sin x\)，可把一个方程拆成两个因式分支。`, '证明过程中分母可能为零；恒等式的共同定义域必须一直保留。'),
      t('General trigonometric solution families', '三角方程的完整解族', 'STEP 可能要求所有实数解，需用整数参数写出周期解族，再按区间筛选。', '主值只是一支，周期与对称共同给出全部解。', r`\cos x=\cos\alpha\iff x=2k\pi\pm\alpha\quad(k\in\mathbb Z)`, '先分解或降阶，列每个因式的解，再合并重复解与端点。', r`例如 \(\sin x=0\) 的所有实数解为 \(x=k\pi\)，而非仅零和圆周率。`, '除以正弦或余弦会漏掉其零点；不同解族重叠时不要重复计数。'),
      t('Auxiliary angles and amplitudes', '辅助角与振幅', '将同角正弦与余弦合为一个平移的三角函数，最值和方程都会简化。', '振幅是两个系数平方和的正平方根，辅助角象限由两系数决定。', r`a\sin x+b\cos x=R\sin(x+\alpha),\quad R=\sqrt{a^2+b^2}`, '对应比较 \(R\cos\alpha=a\)、\(R\sin\alpha=b\)，再处理范围与周期。', r`例如 \(3\sin x+4\cos x=5\sin(x+\alpha)\)，其中 \(\cos\alpha=\frac35\)、\(\sin\alpha=\frac45\)。`, '仅用正切求角会丢失象限；零振幅时无需定义辅助角。'),
      t('Small-angle limits in radians', '弧度下的小角极限', '小角近似比较角接近零时的主导项，适合极限和物理近似，需要区分近似与恒等。', '小角公式使用弧度；相减抵消时可能必须保留更高阶项。', r`\sin x\sim x,\quad\tan x\sim x,\quad\cos x=1-\frac{x^2}2+o(x^2)\quad(x\to0)`, '先看首项是否抵消，再决定保留阶数；将线性倍角一起带入。', r`例如 \(\lim_{x\to0}\frac{1-\cos x}{x^2}=\frac12\)，只用余弦约等于一会丢失关键项。`, '角度单位若为度，系数会改变；近似在远离零的位置不能直接当作精确值。'),
    ],
    exercises: [
      q('trig-factorisation', 'Two trigonometric branches', r`(i) Show that \(\sin3x-\sin x=2\cos2x\sin x\). (ii) Hence solve \(\sin3x=\sin x\) for \(0\le x<2\pi\).`, '使用和差化积，或把三倍角写成二倍角加一倍角，再保留两个因式分支。', [r`Using the sine difference identity, \(\sin3x-\sin x=2\cos(2x)\sin x\). This also follows by expanding \(\sin(2x+x)\).`, r`Thus \(\sin x=0\) or \(\cos2x=0\). In the required interval, the solutions are \(0,\frac\pi4,\frac{3\pi}4,\pi,\frac{5\pi}4,\frac{7\pi}4\). The endpoint \(2\pi\) is excluded.`]),
      q('trig-amplitude', 'Amplitude and a squared integral', r`Let \(f(x)=3\sin x+4\cos x\). (i) Express \(f\) as \(R\sin(x+\alpha)\), with \(R>0\) and \(0<\alpha<\frac\pi2\). (ii) Find its maximum value. (iii) Evaluate \(\int_0^{2\pi}f(x)^2\,dx\).`, '系数平方和给出振幅；积分时展开平方并利用完整周期的对称。', [r`Comparison gives \(R=5\), \(\cos\alpha=\frac35\), \(\sin\alpha=\frac45\). The maximum is 5, attained when \(x+\alpha=\frac\pi2+2k\pi\).`, r`Expand \(f^2=9\sin^2x+24\sin x\cos x+16\cos^2x\). Over a complete period, the first and last squared functions integrate to \(\pi\) and the mixed term integrates to zero. The answer is \(25\pi\).`]),
    ],
  },
  'pure/calculus': {
    bullets: [
      t('Derivative limits and first principles', '导数极限与第一原理', '导数从割线斜率的极限定义；第一原理能解释幂、正弦与余弦求导，不只用于套公式。', '先整理差商，再取极限；分母中的增量不能一开始就设为零。', r`f'(x)=\lim_{h\to0}\frac{f(x+h)-f(x)}h`, '展开并消去常数项，约去增量后再取极限；三角例子需要弧度和基本小角极限。', r`例如 \(\frac{(x+h)^2-x^2}{h}=2x+h\)，所以平方函数的导数为 \(2x\)。`, '连续不一定可导；绝对值在零点连续但左右导数不同。'),
      t('Product, quotient and chain derivatives', '乘积、商与链式求导', '复合结构逐层求导，乘积同时让每个因子轮流变化，再把结果有结构地整理。', '先辨认外层与内层；链式求导必须乘内层导数。', r`(uv)'=u'v+uv',\qquad (f(g(x)))'=f'(g(x))g'(x)`, '先画出表达式的层次；含商时也可尝试改写为负幂后求导。', r`例如 \(\frac d{dx}e^{x^2}=2xe^{x^2}\)，而 \((x\sin x)'=\sin x+x\cos x\)。`, '乘积导数不等于导数的乘积；三角函数求导默认弧度。'),
      t('Implicit and parametric derivatives', '隐函数与参数求导', '变量间未必直接写成显函数，沿关系求导时需保留另一变量对自变量的导数。', '参数曲线先对参数求导，再以横坐标变化率作分母。', r`\frac{dy}{dx}=\frac{\frac{dy}{dt}}{\frac{dx}{dt}}\quad\left(\frac{dx}{dt}\ne0\right)`, '隐式式子逐项使用链式法则；二阶导数需将一阶导数再次对横坐标求导。', r`例如 \(x^2+y^2=1\) 给出 \(y'=-\frac xy\)，但在 y 为零的位置需另查切线。`, '参数速度的横分量为零时，比值公式不适用；不能把参数二阶导数的比值当成曲线二阶导数。'),
      t('Inverse trigonometric derivatives', '反三角函数求导', '利用主值区间和隐式求导，可得到反三角函数导数；这是 STEP 2 已包含的内容。', '使用反正弦导数时限制在开区间负一到一。', r`\frac d{dx}\arctan x=\frac1{1+x^2},\qquad\frac d{dx}\arcsin x=\frac1{\sqrt{1-x^2}}`, '先确认主值与定义域，再为复合输入补上内层导数；可用导数符号证明不等式。', r`例如 \(\frac d{dx}\arctan(2x)=\frac2{1+4x^2}\)，分母始终为正。`, '反三角函数不是三角函数的倒数；端点导数可能不存在或趋于无穷。'),
      t('Stationary points and inflections', '驻点、极值与拐点', '导数和二阶导数的符号变化分别追踪升降与弯曲方向，二者不能相互替代。', '导数为零不保证极值，二阶导数为零也不保证拐点。', r`f'(a)=0\quad\text{is a stationary-point condition}`, '列驻点和不可导点，用两侧符号检验；比较全局最值时补上端点与无穷远行为。', r`例如 \(x^3\) 在零点有水平拐点，\(x^4\) 在零点二阶导数为零但没有凹凸转换。`, '严格极值与非严格极值、局部与全局需要按题意区分；不要只提交候选坐标。'),
    ],
    exercises: [
      q('parametric-tangent', 'A parametric tangent', r`A curve is given by \(x=t^2\), \(y=t^3-3t\). (i) Find \(\frac{dy}{dx}\) when \(t\ne0\). (ii) Find its horizontal tangent points. (iii) Find the tangent at \(t=0\) using the parameter derivatives.`, '水平切线要求纵向变化率为零且横向变化率不为零；零参数处反过来判断。', [r`For \(t\ne0\), \(\frac{dy}{dx}=\frac{3t^2-3}{2t}\). Horizontal tangents occur at \(t=\pm1\), giving points \((1,-2)\) and \((1,2)\).`, r`At \(t=0\), the point is \((0,0)\), with \(\frac{dx}{dt}=0\) and \(\frac{dy}{dt}=-3\ne0\). The tangent is vertical, with equation \(x=0\).`]),
      q('arctan-bound', 'A derivative proves a bound', r`(i) Differentiate \(g(x)=x-\arctan x\). (ii) Prove that \(0<\arctan x<x\) for \(x>0\). (iii) Explain how odd symmetry gives the corresponding comparison for negative \(x\).`, '函数在零点为零，正半轴导数严格为正。', [r`We have \(g'(x)=1-\frac1{1+x^2}=\frac{x^2}{1+x^2}>0\) for \(x>0\). Since \(g(0)=0\), this gives \(\arctan x<x\).`, r`The principal arctangent is increasing and equals zero at zero, so \(\arctan x>0\) for \(x>0\).`, r`For \(x<0\), apply the positive result to \(-x\) and use \(\arctan(-x)=-\arctan x\). The result is \(x<\arctan x<0\).`], true),
    ],
  },
  'pure/integration': {
    bullets: [
      t('Substitution with domains and limits', '带定义域与上下限的换元', '换元同时改写被积式、微分和积分区间，目的是让复合结构变成标准形式。', '换元后全程使用同一个变量，不混用新旧上下限。', r`\int_a^b f(g(x))g'(x)\,dx=\int_{g(a)}^{g(b)}f(u)\,du`, '寻找内部式及其导数，或用三角代换消去根式；处理反解时限定分支。', r`例如 \(\int_0^1 2xe^{x^2}\,dx=\int_0^1 e^u\,du=e-1\)。`, '根式代换可能引入绝对值；新变量不单调时要确认公式适用条件或分段。'),
      t('Integration by parts and boundary terms', '分部积分与边界项', '把一个因子求导、另一个因子积分，常能降低多项式次数或建立原积分的关系。', '先比较变换后是否更简单，并完整保留边界项。', r`\int u\,dv=uv-\int v\,du`, '选择求导后更简单的部分，记录微分与原函数；需要时重复分部并联立原积分。', r`例如 \(\int xe^x\,dx=xe^x-e^x+C\)，其中多项式求导后次数下降。`, '定积分必须计算端点项；无穷端点时先在有限上限应用公式，再取极限。'),
      t('Partial fractions and standard inverse integrals', '部分分式与反三角积分', '有理函数先拆分，线性因式给对数，正二次式经配方常给反正切。', '先除法再拆分，出现不可约二次分母时用一次分子。', r`\int\frac{dx}{a^2+x^2}=\frac1a\arctan\frac xa+C\quad(a>0)`, '配方或提取正系数后匹配标准式；对数项检查绝对值和连通定义区间。', r`例如 \(\int\frac{dx}{x^2+4}=\frac12\arctan\frac x2+C\)，不能遗漏缩放系数。`, '只记形状不追踪尺度会丢系数；原分母为零的点不能跨过当作普通积分。'),
      t('Reduction formulae with base cases', '递推积分与初值', '分部积分或恒等式将索引为 n 的积分联系到较小索引，再用初值逐步求出。', '递推需要注明合法索引与足够的初值。', r`I_n=\int_0^{\frac\pi2}\sin^n x\,dx\quad\Longrightarrow\quad I_n=\frac{n-1}nI_{n-2}\quad(n\ge2)`, '挑出一部分做分部，将剩余平方换成一减另一平方，再整理回原积分。', r`有 \(I_0=\frac\pi2\)、\(I_1=1\)，因此 \(I_2=\frac\pi4\)、\(I_3=\frac23\)。`, '奇偶索引通常落到不同初值；不能把仅对正索引成立的边界消去扩展到零。'),
      t('Improper integrals as separate limits', '反常积分的独立极限', '无穷区间或区间内奇点需要用极限定义；内部奇点的两侧应分别收敛。', '不能用两侧无穷相消代替通常意义的收敛。', r`\int_1^\infty x^{-p}\,dx\ \text{converges exactly when }p>1`, '先保留有限端点求原函数，再分别取各端极限；必要时比较正函数判断收敛。', r`例如 \(\int_1^\infty x^{-2}\,dx=1\)，而负一次幂积分随上限对数增长而发散。`, '对称奇点的柯西主值与通常反常积分不同；即使形式上抵消也不能直接宣布收敛。'),
    ],
    exercises: [
      q('sine-reduction', 'Deriving a reduction formula', r`For integer \(n\ge0\), define \(I_n=\int_0^{\frac\pi2}\sin^n x\,dx\). (i) Show that \(nI_n=(n-1)I_{n-2}\) for \(n\ge2\). (ii) Find \(I_0,I_1,I_4\).`, '把一个正弦因子积分，边界项在给定索引范围内为零。', [r`For \(n\ge2\), integrate \(\sin^{n-1}x\sin x\) by parts. The boundary term \([-\sin^{n-1}x\cos x]_0^{\frac\pi2}\) is zero, so \(I_n=(n-1)\int_0^{\frac\pi2}\sin^{n-2}x\cos^2x\,dx\).`, r`Using \(\cos^2x=1-\sin^2x\), obtain \(I_n=(n-1)(I_{n-2}-I_n)\), hence the recurrence.`, r`The base values are \(I_0=\frac\pi2\), \(I_1=1\). Thus \(I_4=\frac34\cdot\frac12 I_0=\frac{3\pi}{16}\).`], true),
      q('improper-rational', 'A convergent difference of logarithms', r`(i) Decompose \(\frac1{x(x+1)}\) into partial fractions. (ii) Evaluate \(\int_1^\infty\frac{dx}{x(x+1)}\). (iii) Find the exact tail integral starting at \(A>0\).`, '在有限上限合并对数后再取极限，不能把两个发散积分分开赋值。', [r`The decomposition is \(\frac1x-\frac1{x+1}\). With finite upper limit \(R\), an antiderivative is \(\ln x-\ln(x+1)=\ln\frac{x}{x+1}\).`, r`As \(R\to\infty\), this antiderivative tends to zero. The integral from 1 is \(-\ln\frac12=\ln2\).`, r`The tail from \(A\) is \(-\ln\frac A{A+1}=\ln\left(1+\frac1A\right)\). This computation keeps both terms inside a single finite-limit expression.`]),
    ],
  },
};
